<?php
require __DIR__ . '/auth.php'; require_admin();
$artworks = db()->query('SELECT id,title,category,medium,image_path,is_published,sort_order FROM artworks ORDER BY sort_order,id DESC')->fetchAll();
$enquiries = db()->query('SELECT name,email,phone,subject,message,created_at FROM enquiries ORDER BY created_at DESC LIMIT 30')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shanaka Admin</title><link rel="stylesheet" href="/admin/admin.css"></head><body><header><strong>Shanaka Kulathunga — Admin</strong><a href="/" target="_blank">View site</a><a href="/admin/logout.php">Sign out</a></header><main><section><h1>Add artwork</h1><form action="/admin/save-artwork.php" method="post" enctype="multipart/form-data" class="art-form"><input type="hidden" name="id" value=""><label>Title<input name="title" required></label><label>Category<select name="category"><option>oil</option><option>charcoal</option><option>commission</option><option>conceptual</option></select></label><label>Medium<input name="medium" value="Oil on Canvas"></label><label>Artwork image<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></label><label>Sort order<input type="number" name="sort_order" value="0"></label><label class="check"><input type="checkbox" name="is_published" checked> Publish immediately</label><button>Save artwork</button></form></section><section><h2>Artwork</h2><table><thead><tr><th>Image</th><th>Title</th><th>Category</th><th>Published</th><th></th></tr></thead><tbody><?php foreach ($artworks as $art): ?><tr><td><img src="<?= escape($art['image_path']) ?>" alt=""></td><td><?= escape($art['title']) ?><small><?= escape($art['medium']) ?></small></td><td><?= escape($art['category']) ?></td><td><?= $art['is_published'] ? 'Yes' : 'No' ?></td><td><form action="/admin/delete-artwork.php" method="post" onsubmit="return confirm('Delete this artwork?')"><input type="hidden" name="id" value="<?= (int)$art['id'] ?>"><button class="danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></section><section><h2>Recent enquiries</h2><table><thead><tr><th>When</th><th>From</th><th>Message</th></tr></thead><tbody><?php foreach ($enquiries as $item): ?><tr><td><?= escape($item['created_at']) ?></td><td><?= escape($item['name']) ?><small><?= escape($item['email']) ?><br><?= escape($item['phone']) ?></small></td><td><strong><?= escape($item['subject']) ?></strong><br><?= nl2br(escape($item['message'])) ?></td></tr><?php endforeach; ?></tbody></table></section></main></body></html>
